#include <bits/stdc++.h>
using namespace std;

const int INF = INT_MAX;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m, k, c, d;
    cin >> n >> m >> k >> c >> d;

    const int MAXN = 10001;
    struct Edge {
        int to, rev, cap, cost;
    };

    vector<Edge> g[MAXN];
    int nodeCnt = 0;

    vector<int> dist(MAXN), potential(MAXN, 0), level(MAXN), iterArr(MAXN);
    vector<char> done(MAXN);

    auto addNode = [&](int cnt) -> int {
        while (cnt--) g[nodeCnt++].clear();
        return nodeCnt - 1;
    };

    auto addEdge = [&](int u, int v, int cap, int cost) {
        g[u].push_back({v, (int)g[v].size(), cap, cost});
        g[v].push_back({u, (int)g[u].size() - 1, 0, -cost});
    };

    function<bool(int,int)> dijkstra;
    dijkstra = [&](int s, int t) -> bool {
        fill(dist.begin(), dist.begin() + nodeCnt, INF);
        fill(done.begin(), done.begin() + nodeCnt, 0);

        priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
        dist[s] = 0;
        pq.push({0, s});

        while (!pq.empty()) {
            auto [du, u] = pq.top();
            pq.pop();

            if (done[u]) continue;
            done[u] = 1;

            for (const Edge &e : g[u]) {
                int v = e.to;
                if (!e.cap || done[v]) continue;

                int nd = du + potential[u] + e.cost - potential[v];
                if (dist[v] > nd) {
                    dist[v] = nd;
                    pq.push({nd, v});
                }
            }
        }

        return done[t];
    };

    function<bool(int,int)> buildLevel;
    buildLevel = [&](int s, int t) -> bool {
        fill(level.begin(), level.begin() + nodeCnt, 0);
        queue<int> q;
        q.push(s);
        level[s] = 1;

        while (!q.empty()) {
            int u = q.front();
            q.pop();

            for (const Edge &e : g[u]) {
                int v = e.to;
                if (!e.cap || level[v]) continue;

                if (dist[v] == dist[u] + e.cost - potential[v] + potential[u]) {
                    level[v] = level[u] + 1;
                    q.push(v);
                }
            }
        }

        return level[t] != 0;
    };

    function<int(int,int,int)> dfs;
    dfs = [&](int u, int t, int f) -> int {
        if (u == t) return f;

        int sent = 0;
        for (int &i = iterArr[u]; i < (int)g[u].size(); ++i) {
            Edge &e = g[u][i];
            int v = e.to;

            if (!e.cap || level[v] != level[u] + 1) continue;
            if (dist[v] != dist[u] + e.cost - potential[v] + potential[u]) continue;

            int ret = dfs(v, t, min(f, e.cap));
            if (ret) {
                sent += ret;
                f -= ret;
                e.cap -= ret;
                g[v][e.rev].cap += ret;
                if (!f) break;
            }
        }

        return sent;
    };

    auto minCostFlow = [&](int s, int t, int maxFlow) -> pair<int,int> {
        int flow = 0, cost = 0;
        fill(potential.begin(), potential.begin() + nodeCnt, 0);

        while (dijkstra(s, t)) {
            int phaseFlow = 0;

            while (buildLevel(s, t)) {
                fill(iterArr.begin(), iterArr.begin() + nodeCnt, 0);
                int df = dfs(s, t, maxFlow);
                maxFlow -= df;
                phaseFlow += df;
                if (!maxFlow) break;
            }

            flow += phaseFlow;
            cost += (dist[t] + potential[t]) * phaseFlow;

            for (int i = 0; i < nodeCnt; ++i)
                if (dist[i] != INF) potential[i] += dist[i];

            if (!maxFlow) break;
        }

        return {flow, cost};
    };

    int L = max(n, k) * 2;

    addNode(L * n);
    int s = addNode(1);
    int t = addNode(1);

    for (int j = 0; j < k; ++j) {
        int a;
        cin >> a;
        --a;
        addEdge(s, a, 1, 0);
    }

    for (int z = 0; z < m; ++z) {
        int u, v;
        cin >> u >> v;
        --u;
        --v;

        for (int i = 0; i + 1 < L; ++i) {
            int u1 = u + i * n;
            int v1 = v + (i + 1) * n;
            int u2 = u + (i + 1) * n;
            int v2 = v + i * n;

            for (int j = 0; j < k; ++j) {
                int w = c + d * (2 * j + 1);
                addEdge(u1, v1, 1, w);
                addEdge(v2, u2, 1, w);
            }
        }
    }

    for (int i = 0; i + 1 < L; ++i) {
        for (int j = 0; j < n; ++j) {
            int u = j + i * n;
            int v = j + (i + 1) * n;
            addEdge(u, v, INF, c);
        }
    }

    for (int i = 0; i < L; ++i)
        addEdge(i * n, t, INF, 0);

    cout << minCostFlow(s, t, INF).second << '\n';
    return 0;
}
