import java.util.*;

public class Main {
    static class Edge {
        int to, rev, cap, cost;
        Edge(int to, int rev, int cap, int cost) {
            this.to = to;
            this.rev = rev;
            this.cap = cap;
            this.cost = cost;
        }
    }

    static class MinCostFlow {
        final int INF = Integer.MAX_VALUE;
        ArrayList<ArrayList<Edge>> g;
        int[] dist, potential, level, iterArr;
        boolean[] done;
        int nodeCnt;

        MinCostFlow(int maxNodes) {
            g = new ArrayList<>(maxNodes);
            for (int i = 0; i < maxNodes; i++) g.add(new ArrayList<>());
            dist = new int[maxNodes];
            potential = new int[maxNodes];
            level = new int[maxNodes];
            iterArr = new int[maxNodes];
            done = new boolean[maxNodes];
            nodeCnt = 0;
        }

        int addNode(int cnt) {
            int cur = nodeCnt;
            nodeCnt += cnt;
            return cur;
        }

        void addEdge(int u, int v, int cap, int cost) {
            g.get(u).add(new Edge(v, g.get(v).size(), cap, cost));
            g.get(v).add(new Edge(u, g.get(u).size() - 1, 0, -cost));
        }

        boolean dijkstra(int s, int t) {
            Arrays.fill(dist, 0, nodeCnt, INF);
            Arrays.fill(done, 0, nodeCnt, false);
            PriorityQueue<int[]> pq = new PriorityQueue<>(Comparator.comparingInt(a -> a[0]));
            dist[s] = 0;
            pq.offer(new int[]{0, s});
            while (!pq.isEmpty()) {
                int[] cur = pq.poll();
                int du = cur[0], u = cur[1];
                if (done[u]) continue;
                done[u] = true;
                for (Edge e : g.get(u)) {
                    int v = e.to;
                    if (e.cap == 0 || done[v]) continue;
                    int nd = du + potential[u] + e.cost - potential[v];
                    if (dist[v] > nd) {
                        dist[v] = nd;
                        pq.offer(new int[]{nd, v});
                    }
                }
            }
            return done[t];
        }

        boolean buildLevel(int s, int t) {
            Arrays.fill(level, 0, nodeCnt, 0);
            Queue<Integer> q = new LinkedList<>();
            q.offer(s);
            level[s] = 1;
            while (!q.isEmpty()) {
                int u = q.poll();
                for (Edge e : g.get(u)) {
                    int v = e.to;
                    if (e.cap == 0 || level[v] != 0) continue;
                    if (dist[v] == dist[u] + e.cost - potential[v] + potential[u]) {
                        level[v] = level[u] + 1;
                        q.offer(v);
                    }
                }
            }
            return level[t] != 0;
        }

        int dfs(int u, int t, int f) {
            if (u == t) return f;
            int sent = 0;
            for (int i = iterArr[u]; i < g.get(u).size(); i++) {
                Edge e = g.get(u).get(i);
                int v = e.to;
                if (e.cap == 0 || level[v] != level[u] + 1) continue;
                if (dist[v] != dist[u] + e.cost - potential[v] + potential[u]) continue;
                int ret = dfs(v, t, Math.min(f, e.cap));
                if (ret > 0) {
                    sent += ret;
                    f -= ret;
                    e.cap -= ret;
                    g.get(v).get(e.rev).cap += ret;
                    if (f == 0) break;
                }
                iterArr[u] = i + 1;
            }
            return sent;
        }

        int[] minCostFlow(int s, int t, int maxFlow) {
            int flow = 0, cost = 0;
            Arrays.fill(potential, 0, nodeCnt, 0);
            while (dijkstra(s, t)) {
                int phaseFlow = 0;
                while (buildLevel(s, t)) {
                    Arrays.fill(iterArr, 0, nodeCnt, 0);
                    int df = dfs(s, t, maxFlow);
                    maxFlow -= df;
                    phaseFlow += df;
                    if (maxFlow == 0) break;
                }
                flow += phaseFlow;
                cost += (dist[t] + potential[t]) * phaseFlow;
                for (int i = 0; i < nodeCnt; i++) {
                    if (dist[i] != INF) potential[i] += dist[i];
                }
                if (maxFlow == 0) break;
            }
            return new int[]{flow, cost};
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();
        int c = sc.nextInt();
        int d = sc.nextInt();

        final int MAXN = 10001;
        MinCostFlow mcf = new MinCostFlow(MAXN);

        int L = Math.max(n, k) * 2;
        mcf.addNode(L * n);
        int s = mcf.addNode(1);
        int t = mcf.addNode(1);

        for (int j = 0; j < k; j++) {
            int a = sc.nextInt() - 1;
            mcf.addEdge(s, a, 1, 0);
        }

        for (int z = 0; z < m; z++) {
            int u = sc.nextInt() - 1;
            int v = sc.nextInt() - 1;
            for (int i = 0; i + 1 < L; i++) {
                int u1 = u + i * n;
                int v1 = v + (i + 1) * n;
                int u2 = u + (i + 1) * n;
                int v2 = v + i * n;
                for (int j = 0; j < k; j++) {
                    int w = c + d * (2 * j + 1);
                    mcf.addEdge(u1, v1, 1, w);
                    mcf.addEdge(v2, u2, 1, w);
                }
            }
        }

        for (int i = 0; i + 1 < L; i++) {
            for (int j = 0; j < n; j++) {
                int u = j + i * n;
                int v = j + (i + 1) * n;
                mcf.addEdge(u, v, Integer.MAX_VALUE, c);
            }
        }

        for (int i = 0; i < L; i++) {
            mcf.addEdge(i * n, t, Integer.MAX_VALUE, 0);
        }

        int[] result = mcf.minCostFlow(s, t, Integer.MAX_VALUE);
        System.out.println(result[1]);
    }
}
